/* =====================================================================
   Customer / Order reconciliation for uploads:
     FileID 886  Order_Summary_Item_Report_75660_2026-09-03_2026-09-06.csv
     FileID 887  Order_Summary_Item_Report_75660_2026-09-07_2026-09-07.csv
     FileID 900  Order_Summary_Item_Report_75660_2026-09-08_2026-09-09.csv
   PART A is READ-ONLY. PART B (recovery) is wrapped in a transaction that
   ROLLS BACK unless you set @apply = 1 after reviewing PART A.
   No TRUNCATE, no DELETE, no identity reseed, no constraint changes.
   ===================================================================== */
SET NOCOUNT ON;
IF OBJECT_ID('tempdb..#src') IS NOT NULL DROP TABLE #src;
CREATE TABLE #src (
    FileID int, excel_line int, restaurant_name nvarchar(200), invoice_no nvarchar(50),
    customer_name nvarchar(200), mobile_raw nvarchar(50), mobile_digits varchar(50), order_date nvarchar(30),
    name_key nvarchar(200) NULL, mob_key varchar(50) NULL
);

/* ---------- normalised keys (same rules as the application) ---------- */
UPDATE #src SET
    name_key = CASE WHEN LOWER(LTRIM(RTRIM(customer_name))) IN (N'', N'null', N'none', N'nan', N'nat') THEN N'' ELSE LOWER(LTRIM(RTRIM(customer_name))) END,
    mob_key  = mobile_digits;

IF OBJECT_ID('tempdb..#cust') IS NOT NULL DROP TABLE #cust;
SELECT c.Customer_ID,
       c.Customer_Name,
       c.Mobile_Number,
       CASE WHEN LOWER(LTRIM(RTRIM(ISNULL(c.Customer_Name, N'')))) IN (N'', N'null', N'none', N'nan', N'nat') THEN N''
            ELSE LOWER(LTRIM(RTRIM(c.Customer_Name))) END AS name_key,
       REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(ISNULL(c.Mobile_Number, N''))), N' ', N''), N'+', N''), N'-', N''), N'(', N''), N')', N'') AS mob_key
INTO #cust
FROM dbo.Customer c;
UPDATE #cust SET mob_key = LEFT(mob_key, LEN(mob_key) - 2) WHERE mob_key LIKE N'%.0';
CREATE INDEX ix_cust_keys ON #cust (name_key, mob_key, Customer_ID);

/* Expected Customer_ID per invoice under the duplicate rules (lowest ID wins). */
IF OBJECT_ID('tempdb..#recon') IS NOT NULL DROP TABLE #recon;
SELECT s.*,
       CASE
         WHEN s.name_key = N'' AND s.mob_key = '' THEN NULL
         WHEN s.name_key <> N'' AND s.mob_key <> '' THEN
              (SELECT MIN(c.Customer_ID) FROM #cust c WHERE c.name_key = s.name_key AND c.mob_key = s.mob_key)
         WHEN s.name_key <> N'' THEN
              (SELECT MIN(c.Customer_ID) FROM #cust c WHERE c.name_key = s.name_key AND c.mob_key = '')
         ELSE COALESCE(
              (SELECT MIN(c.Customer_ID) FROM #cust c WHERE c.name_key = N'' AND c.mob_key = s.mob_key),
              (SELECT MIN(c.Customer_ID) FROM #cust c WHERE c.mob_key = s.mob_key))
       END AS expected_customer_id,
       b.BillNo, b.Order_ID AS bill_order_id, o.Order_ID, o.Customer_ID AS current_customer_id
INTO #recon
FROM #src s
LEFT JOIN dbo.Bills b ON b.Bill_Number = TRY_CAST(s.invoice_no AS bigint)
LEFT JOIN dbo.[Order] o ON o.Order_ID = b.Order_ID;

/* =====================================================================
   PART A - READ-ONLY REPORT
   ===================================================================== */

-- A1. Per-file summary (source invoices vs actual destination rows)
SELECT r.FileID,
       COUNT(*)                                                         AS source_invoices,
       SUM(CASE WHEN r.BillNo   IS NOT NULL THEN 1 ELSE 0 END)          AS bills_found,
       SUM(CASE WHEN r.Order_ID IS NOT NULL THEN 1 ELSE 0 END)          AS orders_found,
       SUM(CASE WHEN r.name_key = N'' AND r.mob_key = '' THEN 1 ELSE 0 END) AS invoices_without_customer_expected_null,
       SUM(CASE WHEN r.Order_ID IS NOT NULL AND (r.name_key <> N'' OR r.mob_key <> '')
                 AND r.current_customer_id = r.expected_customer_id THEN 1 ELSE 0 END) AS orders_customer_correct,
       SUM(CASE WHEN r.Order_ID IS NOT NULL AND (r.name_key <> N'' OR r.mob_key <> '')
                 AND r.expected_customer_id IS NOT NULL
                 AND ISNULL(r.current_customer_id, -1) <> r.expected_customer_id THEN 1 ELSE 0 END) AS orders_linked_to_wrong_customer,
       SUM(CASE WHEN (r.name_key <> N'' OR r.mob_key <> '') AND r.expected_customer_id IS NULL THEN 1 ELSE 0 END) AS invoices_whose_customer_is_missing
FROM #recon r
GROUP BY r.FileID
ORDER BY r.FileID;

-- A2. Orders linked to a customer that does not satisfy the rules (or whose customer is missing)
SELECT TOP 500 r.FileID, r.excel_line, r.invoice_no, r.customer_name, r.mobile_raw,
       r.Order_ID, r.current_customer_id, cur.Customer_Name AS current_customer_name, cur.Mobile_Number AS current_customer_mobile,
       r.expected_customer_id
FROM #recon r
LEFT JOIN dbo.Customer cur ON cur.Customer_ID = r.current_customer_id
WHERE r.Order_ID IS NOT NULL
  AND (r.name_key <> N'' OR r.mob_key <> '')
  AND (r.expected_customer_id IS NULL OR ISNULL(r.current_customer_id, -1) <> r.expected_customer_id)
ORDER BY r.FileID, r.excel_line;

-- A3. Customers required by the rules that do not exist in dbo.Customer
SELECT name_key, mob_key, MIN(customer_name) AS customer_name, MIN(mobile_raw) AS mobile_raw,
       COUNT(*) AS invoices, MIN(FileID) AS first_file, MIN(excel_line) AS first_excel_line
FROM #recon
WHERE (name_key <> N'' OR mob_key <> '') AND expected_customer_id IS NULL
GROUP BY name_key, mob_key
ORDER BY first_file, first_excel_line;

-- A4. Source invoices with no Bills / Order row
SELECT TOP 500 FileID, excel_line, restaurant_name, invoice_no,
       CASE WHEN BillNo IS NULL THEN 'Bills row missing' ELSE 'Order row missing' END AS problem
FROM #recon
WHERE BillNo IS NULL OR Order_ID IS NULL
ORDER BY FileID, excel_line;

-- A5. Orders from these files pointing at a Customer_ID that does not exist
SELECT o.FileID, COUNT(*) AS orders_with_dangling_customer_id
FROM dbo.[Order] o
WHERE o.FileID IN (886, 887, 900)
  AND o.Customer_ID IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM dbo.Customer c WHERE c.Customer_ID = o.Customer_ID)
GROUP BY o.FileID;

-- A6. Row counts actually stored per file
SELECT 'Customer' AS tbl, FileID, COUNT(*) AS rows_in_db FROM dbo.Customer WHERE FileID IN (886, 887, 900) GROUP BY FileID
UNION ALL SELECT 'Order', FileID, COUNT(*) FROM dbo.[Order] WHERE FileID IN (886, 887, 900) GROUP BY FileID
UNION ALL SELECT 'Bills', FileID, COUNT(*) FROM dbo.Bills WHERE FileID IN (886, 887, 900) GROUP BY FileID
ORDER BY tbl, FileID;

-- A7. Unique indexes / constraints on dbo.Customer. A UNIQUE index on Mobile_Number or
--     Contact_Number makes "different name, same mobile = new customer" impossible to store.
SELECT i.name AS index_name, i.is_unique, i.is_primary_key, c.name AS column_name
FROM sys.indexes i
JOIN sys.index_columns ic ON ic.object_id = i.object_id AND ic.index_id = i.index_id
JOIN sys.columns c ON c.object_id = ic.object_id AND c.column_id = ic.column_id
WHERE i.object_id = OBJECT_ID('dbo.Customer') AND i.is_unique = 1
ORDER BY i.name, ic.key_ordinal;

/* =====================================================================
   PART B - RECOVERY (review PART A first)
   - Inserts only customers that A3 shows are missing.
   - Re-points only the orders that A2 lists, to the customer the rules require.
   - Orders whose source row has neither name nor mobile are not touched.
   - Default is ROLLBACK. Set @apply = 1 to commit.
   ===================================================================== */
DECLARE @apply bit = 0;

BEGIN TRANSACTION;

SELECT CASE WHEN m.name_key = N'' THEN N'' ELSE m.customer_name END,
       NULLIF(m.mobile_raw, N''),
       CASE WHEN m.mobile_raw = N'' THEN N'' ELSE m.mobile_raw END,
       m.first_order_date,
       m.first_file
FROM (
    SELECT name_key, mob_key,
           MIN(customer_name) AS customer_name,
           MIN(mobile_raw)    AS mobile_raw,
           MIN(TRY_CONVERT(datetime, order_date)) AS first_order_date,
           MIN(FileID)        AS first_file
    FROM #recon
    WHERE (name_key <> N'' OR mob_key <> '') AND expected_customer_id IS NULL
    GROUP BY name_key, mob_key
) m;
PRINT CONCAT('Customers inserted: ', @@ROWCOUNT);

-- refresh keys with the new customers and recompute the expected IDs
SELECT c.Customer_ID, c.Customer_Name, c.Mobile_Number,
       CASE WHEN LOWER(LTRIM(RTRIM(ISNULL(c.Customer_Name, N'')))) IN (N'', N'null', N'none', N'nan', N'nat') THEN N''
            ELSE LOWER(LTRIM(RTRIM(c.Customer_Name))) END,
       REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(ISNULL(c.Mobile_Number, N''))), N' ', N''), N'+', N''), N'-', N''), N'(', N''), N')', N'')
FROM dbo.Customer c
WHERE NOT EXISTS (SELECT 1 FROM #cust x WHERE x.Customer_ID = c.Customer_ID);

UPDATE r SET expected_customer_id =
       CASE
         WHEN r.name_key <> N'' AND r.mob_key <> '' THEN
              (SELECT MIN(c.Customer_ID) FROM #cust c WHERE c.name_key = r.name_key AND c.mob_key = r.mob_key)
         WHEN r.name_key <> N'' THEN
              (SELECT MIN(c.Customer_ID) FROM #cust c WHERE c.name_key = r.name_key AND c.mob_key = '')
         ELSE COALESCE(
              (SELECT MIN(c.Customer_ID) FROM #cust c WHERE c.name_key = N'' AND c.mob_key = r.mob_key),
              (SELECT MIN(c.Customer_ID) FROM #cust c WHERE c.mob_key = r.mob_key))
       END
FROM #recon r
WHERE (r.name_key <> N'' OR r.mob_key <> '');

UPDATE o SET o.Customer_ID = r.expected_customer_id
FROM dbo.[Order] o
JOIN #recon r ON r.Order_ID = o.Order_ID
WHERE (r.name_key <> N'' OR r.mob_key <> '')
  AND r.expected_customer_id IS NOT NULL
  AND ISNULL(o.Customer_ID, -1) <> r.expected_customer_id;
PRINT CONCAT('Orders re-linked: ', @@ROWCOUNT);

-- after-check: must be 0 wrong links and 0 missing customers
SELECT
    SUM(CASE WHEN r.Order_ID IS NOT NULL AND (r.name_key <> N'' OR r.mob_key <> '')
              AND ISNULL(o.Customer_ID, -1) <> ISNULL(r.expected_customer_id, -2) THEN 1 ELSE 0 END) AS still_wrong,
    SUM(CASE WHEN (r.name_key <> N'' OR r.mob_key <> '') AND r.expected_customer_id IS NULL THEN 1 ELSE 0 END) AS still_missing_customer
FROM #recon r
LEFT JOIN dbo.[Order] o ON o.Order_ID = r.Order_ID;

IF @apply = 1
BEGIN
    COMMIT TRANSACTION;
    PRINT 'Recovery COMMITTED.';
END
ELSE
BEGIN
    ROLLBACK TRANSACTION;
    PRINT 'Dry run only - ROLLED BACK. Set @apply = 1 to commit.';
END;
